const nums = [10, 2, 21, 1, 100, 3];

[...nums].sort()
// [1, 10, 100, 2, 21, 3] - ZLE! posortowane jak TEKST, nie jak liczby

[...nums].sort((a, b) => a - b)
// [1, 2, 3, 10, 21, 100] - POPRAWNIE, rosnaco liczbowo

const nums = [10, 2, 21, 1, 100, 3];

console.log([...nums].sort((a, b) => a - b)); // [1, 2, 3, 10, 21, 100] - rosnaco
console.log([...nums].sort((a, b) => b - a)); // [100, 21, 10, 3, 2, 1] - malejaco

const products = [
  { name: "Laptop", price: 3000 },
  { name: "Book", price: 39 },
  { name: "Tablet", price: 800 },
];

const byPrice = [...products].sort((a, b) => a.price - b.price);
console.log(byPrice.map(p => p.name)); // ['Book', 'Tablet', 'Laptop']

const byName = [...products].sort((a, b) => a.name.localeCompare(b.name));
console.log(byName.map(p => p.name)); // ['Book', 'Laptop', 'Tablet']

const ceny = [100, 25, 9, 250, 3];
console.log(ceny.sort()); // BLEDNIE: [100, 25, 250, 3, 9]
// posortowane jak TEKST: '100' < '25' < '250' < '3' < '9'

