const pracownicy = [
  { imie: "Marta", wiek: 34 },
  { imie: "Tomek", wiek: 19 },
  { imie: "Ola", wiek: 41 }
];

const posortowani = [...pracownicy].sort((a, b) => a.wiek - b.wiek);
console.log(posortowani.map(p => `${p.imie}: ${p.wiek}`));
// ['Tomek: 19', 'Marta: 34', 'Ola: 41']

const pracownicy = [{ imie: "Zosia" }, { imie: "Ala" }, { imie: "Marek" }];
const posortowani = [...pracownicy].sort((a, b) => a.imie.localeCompare(b.imie));
console.log(posortowani.map(p => p.imie)); // ['Ala', 'Marek', 'Zosia']

const ceny1 = [100, 25, 9, 250, 3];
console.log([...ceny1].sort()); // [100, 25, 250, 3, 9] - BLEDNIE

const ceny2 = [100, 25, 9, 250, 3];
console.log([...ceny2].sort((a, b) => a - b)); // [3, 9, 25, 100, 250] - POPRAWNIE

const produkty = [
  { nazwa: "Kubek", cena: 25 },
  { nazwa: "Laptop", cena: 3000 },
  { nazwa: "Notes", cena: 15 }
];

const posortowane = [...produkty].sort((a, b) => b.cena - a.cena);
console.log(posortowane.map(p => p.nazwa)); // ['Laptop', 'Kubek', 'Notes']

function posortujRosnaco(tablica) {
  return [...tablica].sort((a, b) => a - b);
}

const oryginal = [7, 2, 9, 1];
console.log(posortujRosnaco(oryginal)); // [1, 2, 7, 9]
console.log(oryginal); // [7, 2, 9, 1] - NIEZMIENIONY
